import { Component, Element, Event, EventEmitter, h, Host, Listen, Prop, Watch } from '@stencil/core';
import { TreeViewSize } from '../../types';

/**
 * @slot default - default slot for tree nodes
 */
@Component({
  tag: 'groupui-tree-view',
  styleUrl: 'tree-view.scss',
  shadow: true,
})
export class TreeView {
  @Element() host: HTMLElement;

  /**
   * If true, the tree nodes are selectable via checkbox
   */
  @Prop({ reflect: true }) readonly selectable = false;

  /**
   * If true, the active indicator is hidden
   */
  @Prop({ reflect: true }) readonly hideIndicator = false;

  /**
   * Size of all tree nodes. Available sizes are 'm' (default) and 's'
   */
  @Prop({ reflect: true }) readonly size: TreeViewSize = 'm';

  /**
   * Deactivates the active state management.
   */
  @Prop({ reflect: true }) readonly manualMode: boolean = false;

  /**
   * dispatched when active state changes => 'event.detail' delivers the active node
   */
  @Event({ bubbles: false }) groupuiActiveChanged: EventEmitter<{ node: HTMLGroupuiTreeNodeElement }>;

  /**
   * dispatched when one node gets selected or deselected => 'event.detail' delivers all selected nodes
   */
  @Event({ bubbles: true }) groupuiSelectionChanged: EventEmitter<{ selected: HTMLGroupuiTreeNodeElement[] }>;

  private activeIndex: number = -1;

  @Watch('selectable')
  updateSelectablePropOfChild() {
    const treeNodes = this.treeNodes();
    treeNodes.forEach((node: HTMLGroupuiTreeNodeElement) => {
      node.selectable = this.selectable;
    });
  }

  @Watch('hideIndicator')
  updateHideIndicatorPropOfChild() {
    const treeNodes = this.treeNodes();
    treeNodes.forEach((node: HTMLGroupuiTreeNodeElement) => {
      node.hideIndicator = this.hideIndicator;
    });
  }

  @Watch('size')
  updateSizePropOfChild() {
    const treeNodes = this.treeNodes();
    treeNodes.forEach((node: HTMLGroupuiTreeNodeElement) => {
      node.size = this.size;
    });

    const groups = Array.from(this.host.querySelectorAll('groupui-tree-group'));
    groups.forEach((group: HTMLGroupuiTreeGroupElement) => {
      group.size = this.size;
    });
  }

  @Listen('click')
  handleClick(event: Event): void {
    const item = (event.target as HTMLElement).closest('groupui-tree-node');
    if (this.manualMode || !item || item.disabled) return;

    this.treeNodes().forEach((node) => {
      node.removeAttribute('active');
    });
    item.setAttribute('active', '');
    this.groupuiActiveChanged.emit({ node: item });
  }

  @Listen('focusin')
  onFocus() {
    if (this.activeIndex > -1) return;
    this.activeIndex = 0;
    const activeNode: HTMLGroupuiTreeNodeElement = this.treeNodes().find((node) => node.active);
    if (activeNode) {
      const collapsedParent: HTMLGroupuiTreeNodeElement = activeNode.closest('groupui-tree-node[collapsed]');
      this.activeIndex = this.focusableNodes().indexOf(collapsedParent || activeNode);
    }
    this.switchFocus();
  }

  @Listen('keydown')
  onKeyDown(event: KeyboardEvent) {
    event.preventDefault();
    if (event.code === 'Tab') {
      if (this.activeIndex > -1) {
        this.treeNodes().forEach((node) => node.blur());
        if (event.shiftKey && this.host.previousElementSibling) {
          const prevHTMLElement = this.host.previousElementSibling as HTMLElement;
          prevHTMLElement.focus && prevHTMLElement.focus();
        } else if (this.host.nextElementSibling) {
          const nextHTMLElement = this.host.nextElementSibling as HTMLElement;
          nextHTMLElement.focus && nextHTMLElement.focus();
        }
        this.activeIndex = -1;
        return;
      }
    } else if (event.code === 'Home') {
      this.activeIndex = 0;
    } else if (event.code === 'End') {
      this.activeIndex = this.focusableNodes().length - 1;
    } else if (event.code === 'ArrowDown') {
      this.activeIndex = Math.min(this.activeIndex + 1, this.focusableNodes().length - 1);
    } else if (event.code === 'ArrowUp') {
      this.activeIndex = Math.max(this.activeIndex - 1, 0);
    } else if (event.code === 'ArrowRight') {
      const currentNode = this.focusableNodes()[this.activeIndex];
      if (currentNode.collapsed) {
        currentNode.collapsed = false;
      } else if (currentNode.querySelector('groupui-tree-node')) {
        this.activeIndex += 1;
      } else {
        return;
      }
    } else if (event.code === 'ArrowLeft') {
      const currentNode = this.focusableNodes()[this.activeIndex];
      if (!currentNode.collapsed && currentNode.querySelector('groupui-tree-node')) {
        currentNode.collapsed = true;
      } else if (currentNode.parentElement.nodeName === 'GROUPUI-TREE-NODE') {
        this.activeIndex = this.focusableNodes().indexOf(currentNode.parentElement as HTMLGroupuiTreeNodeElement);
      } else {
        return;
      }
    } else if (event.code === 'Enter') {
      const currentNode = this.focusableNodes()[this.activeIndex];
      if (currentNode.querySelector('groupui-tree-node')) {
        currentNode.collapsed = !currentNode.collapsed;
      } else {
        this.treeNodes().forEach((node) => {
          node.active = false;
        });
        currentNode.active = true;
      }
      return;
    } else if (event.code === 'Space') {
      const currentNode = this.focusableNodes()[this.activeIndex];
      if (currentNode.selectable) {
        currentNode.shadowRoot.querySelector('groupui-checkbox').click();
      }
      return;
    }
    this.switchFocus();
  }

  componentWillRender() {
    this.updateSelectablePropOfChild();
    this.updateHideIndicatorPropOfChild();
    this.updateSizePropOfChild();
  }

  componentDidLoad() {
    this.addChangeEventListeners();
  }

  private handleSlotChange = (e: Event): void => {
    e.stopPropagation();
    this.updateSelectablePropOfChild();
    this.updateHideIndicatorPropOfChild();
    this.updateSizePropOfChild();
    this.addChangeEventListeners();
  };

  private addChangeEventListeners() {
    this.rootNodes().forEach((tree) => {
      tree.removeEventListener('nodeSelectedEvent', this.emitSelectedNodes);
      tree.addEventListener('nodeSelectedEvent', this.emitSelectedNodes);
    });
  }

  private emitSelectedNodes = () => {
    this.groupuiSelectionChanged.emit({
      selected: this.treeNodes().filter((node) => node.selected),
    });
  };

  private rootNodes(): HTMLGroupuiTreeNodeElement[] {
    const childNodes = Array.from(this.host.querySelectorAll('groupui-tree-node groupui-tree-node')) || [];
    return this.treeNodes().filter((node) => childNodes.indexOf(node) < 0);
  }

  private treeNodes(): HTMLGroupuiTreeNodeElement[] {
    return Array.from(this.host.querySelectorAll('groupui-tree-node')) || [];
  }

  private focusableNodes(): HTMLGroupuiTreeNodeElement[] {
    const hiddenNodes = [];
    this.treeNodes().forEach((node) => {
      if (node.collapsed) {
        hiddenNodes.push(...Array.from(node.querySelectorAll('groupui-tree-node')));
      }
    });
    return this.treeNodes()
      .filter((node) => !node.disabled)
      .filter((node) => hiddenNodes.indexOf(node) < 0);
  }

  private switchFocus() {
    if (this.activeIndex >= 0) {
      this.focusableNodes()[this.activeIndex].focus();
    }
  }

  render() {
    return (
      <Host role="tree" aria-multiselectable={this.selectable ? 'true' : 'false'}>
        <slot onSlotchange={this.handleSlotChange}></slot>
      </Host>
    );
  }
}
